(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*20+Math.cos(y*0.012-t*0.18)*15;
  const w1y = Math.cos(y*0.018-t*0.22)*20+Math.sin(x*0.014+t*0.3)*15;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.025+my*0.01+t*0.4)*10+Math.cos(my*0.02-t*0.35)*8;
  const w2y = Math.cos(my*0.02-mx*0.015-t*0.38)*10+Math.sin(mx*0.018+t*0.45)*8;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.05],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.07],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.04],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.09],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.055],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.065],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*40,0.11,2.1,0.08],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*50,0.085,1.8,0.05]
  ];
  let act=0,inh=0,act2=0;
  for(const[sX,sY,f,sp,f2]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const dc=Math.exp(-d*0.003);
    act+=(Math.sin(d*f-t*sp)+Math.sin(d*f*1.618-t*sp*0.7)*0.5)*dc;
    inh+=(Math.sin(d*f*0.7+t*sp*0.6+1.5)+Math.sin(d*f2*0.5-t*sp*0.4)*0.3)*dc;
    act2+=Math.sin(d*f*1.3+t*sp*0.8+2.0)*dc*0.4;
  }
  act/=8;inh/=8;act2/=8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)*0.4+Math.sin(sx*0.03-sy*0.04+t*1.1)*0.4+Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15+Math.sin(sx*0.08+sy*0.06-t*1.5)*0.2+Math.sin(sx*0.06-sy*0.09+t*1.8)*0.2)/1.5;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.03*1.618-ang*5+t*0.9)*0.5)*0.3;
  const cellX=Math.sin(sx*0.15)*Math.sin(sy*0.15),cellY=Math.sin(sx*0.15+1.7)*Math.sin(sy*0.15+2.3);
  const cell=(cellX+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(cellY*3+t*0.7)*0.3)*0.4;
  const rd1=act-inh*0.7+bg*0.3+spiral,rd2=act2+cell*0.5-inh*0.3;
  const reaction=Math.tanh(rd1*2.2+rd2*0.8);
  const detail=Math.sin(sx*0.3+sy*0.2+t*3)*Math.sin(sx*0.25-sy*0.35-t*2.5)*0.15;
  const edgeStr=Math.abs(reaction)>0.6?1.2:Math.abs(reaction)>0.3?1.05:0.95;
  const blend=reaction*0.6+Math.tanh(cell*1.5)*0.2+detail*0.2;
  const v=blend*0.5+0.5;
  const pal=[[12,15,72],[18,60,108],[20,120,120],[28,165,130],[180,195,60],[220,170,50],[215,120,60],[195,75,75],[140,45,75],[60,20,60],[12,15,72]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i,sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const vigD=Math.sqrt((x-cx)**2+(y-cy)**2)/300,vig=1.0-vigD*vigD*0.25;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edgeStr*vig)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edgeStr*vig)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edgeStr*vig)|0
  ];
}
